const files = {"index.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <title>AvacaDO — The Rebel Road</title><link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n<main id=\"app\">\n  <section id=\"startScreen\" class=\"screen parchment\">\n    <p class=\"eyebrow\">A medieval rebellion against the green crown</p>\n    <h1>AVACA<span>DO</span></h1><p class=\"subtitle\">The Rebel Road</p>\n    <div class=\"start-art\"><i>🥑</i><b>VS</b><i>🍅</i></div>\n    <p class=\"intro\">Race across the royal realm before the Cado King’s 30-turn doomsday clock reaches midnight.</p>\n    <button id=\"newGameBtn\" class=\"primary\">Begin the Rebellion</button>\n    <button id=\"continueBtn\" class=\"secondary hidden\">Continue Saved Game</button>\n    <button data-open=\"rules\" class=\"linkbtn\">Read the Royal Decree (Rules)</button>\n  </section>\n\n  <section id=\"setupScreen\" class=\"screen parchment hidden\">\n    <h2>Gather the Rebels</h2><p>Choose up to five champions. Empty seats become computer rebels.</p>\n    <div id=\"playerSetup\" class=\"setup-grid\"></div>\n    <div class=\"setup-options\"><label>Doomsday <select id=\"difficulty\"><option value=\"easy\">Easy — 36 turns</option><option value=\"normal\" selected>Normal — 30 turns</option><option value=\"hard\">Hard — 24 turns</option></select></label><label><input type=\"checkbox\" id=\"fillAi\" checked> Fill empty seats with AI</label></div>\n    <div class=\"row\"><button id=\"backBtn\" class=\"secondary\">Back</button><button id=\"startBtn\" class=\"primary\">Start Game</button></div>\n  </section>\n\n  <section id=\"gameScreen\" class=\"hidden\">\n    <header><div class=\"brand\">AVACA<span>DO</span></div><div id=\"turnBanner\">Preparing the rebellion…</div><div class=\"header-controls\"><button id=\"musicBtn\" title=\"Toggle music\">♫ Music</button><button id=\"muteBtn\" title=\"Toggle sound\">🔊</button><button data-open=\"rules\">Rules</button><button id=\"pauseBtn\">Pause</button></div></header>\n    <div class=\"game-layout\">\n      <aside class=\"panel players-panel\"><h3>Rebel Roster</h3><div id=\"playerList\"></div></aside>\n      <section class=\"board-wrap\"><div id=\"board\" aria-label=\"AvacaDO game board\"><div id=\"clock\"><div class=\"crown\">♛</div><strong>DOOMSDAY</strong><span id=\"clockNumber\">30</span><small>turns remain</small><div class=\"clock-bar\"><i id=\"clockFill\"></i></div><em id=\"clockWarning\">The Cado King watches.</em></div></div></section>\n      <aside class=\"panel action-panel\"><h3>Turn Actions</h3><div id=\"dice\" class=\"dice\"><b>?</b><b>?</b></div><p id=\"actionText\">Roll when it is your turn.</p><button id=\"rollBtn\" class=\"primary\">Roll Two Dice</button><button id=\"endBtn\" class=\"secondary\" disabled>End Turn</button><hr><h3>Rebel Market</h3><div id=\"shop\"></div><p class=\"tiny\">Spend points only on your own turn.</p></aside>\n    </div>\n    <footer><button id=\"restartBtn\">Restart</button><button id=\"resetSaveBtn\">Reset Save</button><span>75 spaces · 20 event spaces · local multiplayer</span></footer>\n  </section>\n\n  <div id=\"modal\" class=\"modal hidden\" role=\"dialog\" aria-modal=\"true\"><div class=\"modal-card\"><button id=\"closeModal\" class=\"close\">×</button><div id=\"modalContent\"></div></div></div>\n</main><script src=\"game.js?v=board-one-loop\"></script>\n</body></html>\n","styles.css":"@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@600;700;800&family=Nunito:wght@500;700;800&display=swap');\n:root{--ink:#281b12;--gold:#e7b94b;--cream:#f6e9bd;--red:#a43832;--green:#496739;--wood:#4e2e1c}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at center,#5d7847,#1c3026 72%);color:var(--ink);font-family:Nunito,Arial,sans-serif}button,select{font:inherit}button{cursor:pointer;border:0;border-radius:8px;padding:9px 13px;font-weight:800;color:#fff;background:#765034;box-shadow:0 3px 0 #321d12;transition:.15s transform,.15s filter}button:hover:not(:disabled){transform:translateY(-2px);filter:brightness(1.13)}button:active:not(:disabled){transform:translateY(2px);box-shadow:none}button:disabled{opacity:.45;cursor:not-allowed}.primary{background:var(--red);font-family:Cinzel;font-size:15px}.secondary{background:#6d6a54}.linkbtn{background:none;box-shadow:none;color:#6c3523;text-decoration:underline}.hidden{display:none!important}.screen{width:min(780px,94vw);margin:5vh auto;padding:40px;border:10px solid #583720;border-radius:18px;text-align:center;box-shadow:0 18px 50px #0b1712}.parchment{background:linear-gradient(125deg,#f6e9bd,#d8bd7c 50%,#f1dfa9);background-image:linear-gradient(125deg,#f6e9bdcc,#d8bd7ccc 50%,#f1dfa9cc),radial-gradient(#98754855 1px,transparent 1px);background-size:auto,6px 6px}h1,h2,h3,.brand{font-family:Cinzel;margin:.15em 0}h1{font-size:clamp(54px,12vw,100px);letter-spacing:2px;color:#355b38;text-shadow:3px 3px #eed16b}h1 span,.brand span{color:#b54432}.eyebrow{text-transform:uppercase;letter-spacing:2px}.subtitle{font-family:Cinzel;font-size:22px;margin-top:-9px}.start-art{font-size:75px;display:flex;justify-content:center;align-items:center;gap:25px;margin:18px}.start-art b{font-size:20px;color:#a43832}.intro{max-width:520px;margin:15px auto 25px;font-size:18px}.screen .primary,.screen .secondary{margin:7px}.setup-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:25px 0}.setup-person{border:2px solid #8c7048;border-radius:10px;padding:9px;background:#fff7d8}.setup-person select{width:100%;margin-top:7px}.setup-person .fruit{font-size:32px}.setup-options{display:flex;gap:24px;justify-content:center;align-items:center;flex-wrap:wrap}.setup-options select{padding:4px}.row{margin-top:25px}header{height:65px;padding:9px 18px;display:flex;align-items:center;justify-content:space-between;background:#2d2119;color:#fff4c7;border-bottom:3px solid var(--gold)}.brand{font-size:25px;color:#7faa5a}.header-controls{display:flex;gap:7px}.header-controls button,footer button{padding:6px 9px;font-size:13px;box-shadow:none}.game-layout{display:grid;grid-template-columns:210px minmax(530px,1fr) 210px;gap:14px;max-width:1370px;margin:10px auto;padding:0 10px}.panel{background:linear-gradient(135deg,#f2dfaa,#cfa96d);border:4px solid #57351f;border-radius:13px;padding:12px;box-shadow:0 7px 12px #14231999}.panel h3{text-align:center;font-size:15px}.board-wrap{min-width:0}.board{position:relative}#board{height:min(76vh,760px);min-height:560px;position:relative;border-radius:28px;background:radial-gradient(ellipse,#a8bb72 0 31%,#708e5b 32% 35%,#345636 36% 49%,#243f2c 50%);border:8px solid #8c6334;box-shadow:inset 0 0 0 4px #e7c973,0 10px 18px #14231999}.tile{position:absolute;width:38px;height:38px;transform:translate(-50%,-50%);border:3px solid #402618;border-radius:9px;text-align:center;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:7px;font-weight:900;line-height:8px;box-shadow:0 2px 0 #281b12;transition:filter .2s,transform .2s;z-index:2}.tile:hover{filter:brightness(1.22);z-index:5}.tile .num{position:absolute;top:1px;left:3px;font-size:8px}.tile.normal{background:#e9d292}.tile.roll{background:#7eb6cc}.tile.back{background:#d67a69}.tile.swap{background:#ad8dcd}.tile.event{background:#e2ad40}.tile.bad{background:#6a4b5b;color:#fff}.tile.goal{background:#69a65a;color:#fff}.tile-label{max-width:34px}.piece{position:absolute;font-size:24px;line-height:24px;z-index:9;filter:drop-shadow(1px 2px 0 #222);transition:left .25s ease,top .25s ease,transform .2s}.piece.active{transform:scale(1.35);filter:drop-shadow(0 0 5px #fff)}#clock{position:absolute;width:235px;height:235px;left:50%;top:50%;transform:translate(-50%,-50%);border-radius:50%;border:8px solid #6b4226;background:radial-gradient(circle,#f9edbc,#c48b3d);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;box-shadow:0 0 0 7px #9a6d38}.crown{font-size:36px;color:#9c312b;margin-bottom:-5px}#clock strong{font-family:Cinzel;font-size:16px}#clockNumber{font-family:Cinzel;font-size:55px;line-height:58px;color:#a32d27}.clock-bar{height:10px;width:155px;background:#57351f;border-radius:6px;overflow:hidden;margin:8px}.clock-bar i{display:block;height:100%;width:100%;background:#5c993f;transition:width .5s}.clock-bar.danger i{background:#bc3c31}#clockWarning{font-size:10px}.player-card{position:relative;padding:7px 4px 7px 34px;border-bottom:1px solid #8d6841;font-size:12px}.player-card .fruit{position:absolute;left:4px;top:6px;font-size:25px}.player-card.active{background:#fff0b6;border-radius:6px}.player-card.dead{opacity:.48}.player-card .name{font-weight:900}.player-card small{display:block}.dice{height:63px;display:flex;gap:9px;justify-content:center;align-items:center}.dice b{width:48px;height:48px;border-radius:9px;background:#f6edcf;border:2px solid #5a3924;display:grid;place-content:center;font-family:Cinzel;font-size:28px;box-shadow:2px 3px #6a4931}.dice.rolling b{animation:shake .12s infinite}@keyframes shake{50%{transform:rotate(9deg) translateY(-4px)}}#actionText{font-size:13px;text-align:center;min-height:42px}.action-panel .primary,.action-panel .secondary{width:100%;margin:5px 0}.action-panel hr{border:0;border-top:1px solid #947144;margin:13px 0}.shop-item{width:100%;background:#6a4930;margin:4px 0;padding:7px;font-size:11px;text-align:left}.tiny{font-size:10px;margin:7px 0;color:#56402d}footer{color:#f5df9b;text-align:center;padding:5px;font-size:12px}.modal{position:fixed;inset:0;background:#111b18cc;display:grid;place-items:center;z-index:30;padding:15px}.modal-card{position:relative;width:min(600px,95vw);max-height:88vh;overflow:auto;padding:28px;background:linear-gradient(135deg,#f8e9b8,#d6b26d);border:7px solid #56341f;border-radius:15px;box-shadow:0 15px 35px #000}.close{position:absolute;right:9px;top:7px;font-size:22px;padding:0 8px;background:none;color:#51321f;box-shadow:none}.event-card{border:3px dashed #8b3a2e;padding:18px;background:#fff1ba;text-align:center}.event-card .card-icon{font-size:50px}.event-card h2{color:#9a302a}.rules h2{color:#476a3c}.rules h3{margin-top:19px}.rules p{line-height:1.45}.win{text-align:center}.win .winner-fruit{font-size:80px}.win h2{font-size:31px;color:#a43832}.pause{text-align:center}.pause h2{font-size:35px}.turn-toast{animation:pulse .6s 2}@keyframes pulse{50%{filter:brightness(1.5)}}\n@media(max-width:1050px){.game-layout{grid-template-columns:170px minmax(480px,1fr) 170px}.tile{width:32px;height:32px;font-size:6px}.tile-label{max-width:35px}#clock{width:205px;height:205px}}@media(max-width:800px){header{height:auto;flex-wrap:wrap;justify-content:center;gap:6px}.game-layout{grid-template-columns:1fr}.players-panel,.action-panel{max-width:650px;margin:auto;width:100%}#board{height:600px}.setup-grid{grid-template-columns:repeat(2,1fr)}}\n\r\n","game.js":"/* AvacaDO: standalone browser board game. State is persisted locally. */\nconst $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];\nconst FRUITS=[['Tomato','🍅','#db5147'],['Strawberry','🍓','#d64549'],['Orange','🍊','#e78928'],['Potato','🥔','#aa8452'],['Banana','🍌','#e6cb43']];\nconst TYPES={normal:['normal','REST'],roll:['roll','ROLL AGAIN'],back:['back','BACK 5'],swap:['swap','SWAP'],event:['event','EVENT'],bad:['bad','BAD LUCK'],goal:['goal','GOAL']};\nconst EVENTS=[\n ['Royal Shortcut','🌿','Move forward 6 spaces.',p=>move(p,6)],['Rebel Feast','🍞','Gain 6 points.',p=>p.points+=6],['Tax Collector','🪙','Lose 4 points.',p=>p.points=Math.max(0,p.points-4)],['Hidden Tunnel','🕳️','Move forward 4 spaces.',p=>move(p,4)],['Royal Mud','🫧','Move back 4 spaces.',p=>move(p,-4)],['Rebel Banner','🚩','Take another turn!',p=>p.extra=true],['King’s Decree','📜','Skip your next turn.',p=>p.skip++],['Secret Map','🗺️','Gain 8 points.',p=>p.points+=8],['Cado Guard','🛡️','A rival is blocked for one turn.',p=>{let r=rival(p);if(r)r.skip++}],['Market Day','🏰','Gain 4 points.',p=>p.points+=4],['Ripe Escape','💨','Move forward 3 spaces.',p=>move(p,3)],['Spoiled Supplies','🦠','Lose 3 points.',p=>p.points=Math.max(0,p.points-3)],['Mirror Portal','🪞','Swap places with a rival.',p=>swap(p,rival(p))],['Lucky Seed','🌱','Gain a free +3 boost.',p=>p.boost3=1],['Sabotage','💣','A rival loses 5 points.',p=>{let r=rival(p);if(r)r.points=Math.max(0,r.points-5)}],['Royal Road','🐎','Move forward 5 spaces.',p=>move(p,5)],['Rebel Spy','🕵️','Reveal: gain 2 points and another turn.',p=>{p.points+=2;p.extra=true}],['Broken Cart','🛒','Move back 3 spaces.',p=>move(p,-3)],['Shield Charm','✨','Gain 2 turns of immunity.',p=>p.immunity=Math.max(p.immunity,2)],['Cado Curse','👑','Doomsday loses 2 turns!',p=>game.clock=Math.min(game.maxClock,game.clock+2)] ];\nlet game=null, audio=null;\nfunction tileType(i){if(i===75)return'goal';const event=[3,7,11,15,19,23,27,31,35,39,43,47,51,55,59,63,67,69,71,73];if(event.includes(i))return'event';if([9,29,49,65].includes(i))return'roll';if([13,33,53].includes(i))return'back';if([17,37,57].includes(i))return'swap';if([21,45,61].includes(i))return'bad';return'normal'}\nfunction save(){if(game)localStorage.setItem('avacadoSave',JSON.stringify(game));}\nfunction clearSave(){localStorage.removeItem('avacadoSave');$('#continueBtn').classList.add('hidden');}\nfunction show(id){$$('.screen,#gameScreen').forEach(x=>x.classList.add('hidden'));$('#'+id).classList.remove('hidden')}\nfunction setup(){show('setupScreen');$('#playerSetup').innerHTML=FRUITS.map((f,i)=>`<div class=\"setup-person\"><div class=\"fruit\">${f[1]}</div><b>${f[0]}</b><select data-seat=\"${i}\"><option value=\"human\">Human</option><option value=\"ai-easy\">AI: Easy</option><option value=\"ai-normal\" ${i?'selected':''}>AI: Normal</option><option value=\"off\" ${i?'':'selected'}>Empty</option><option value=\"ai-hard\">AI: Hard</option></select></div>`).join('')}\nfunction newGame(){let chosen=$$('#playerSetup select').map((s,i)=>({seat:i,type:s.value})).filter(x=>x.type!=='off');if($('#fillAi').checked){for(let i=0;chosen.length<5&&i<5;i++)if(!chosen.some(x=>x.seat===i))chosen.push({seat:i,type:'ai-normal'})}if(!chosen.some(x=>x.type==='human')){alert('Choose at least one human rebel.');return}let max={easy:36,normal:30,hard:24}[$('#difficulty').value];game={players:chosen.map((x,n)=>({id:n,name:FRUITS[x.seat][0],fruit:FRUITS[x.seat][1],color:FRUITS[x.seat][2],ai:x.type.startsWith('ai'),level:x.type.split('-')[1]||'normal',pos:0,points:4,skip:0,immunity:0,boost5:0,boost3:0,extra:false})),current:0,clock:max,maxClock:max,phase:'roll',paused:false,over:false};show('gameScreen');buildBoard();render();startTurn()}\nfunction buildBoard(){let b=$('#board');b.innerHTML='<div id=\"clock\"><div class=\"crown\">♛</div><strong>DOOMSDAY</strong><span id=\"clockNumber\">30</span><small>turns remain</small><div class=\"clock-bar\"><i id=\"clockFill\"></i></div><em id=\"clockWarning\">The Cado King watches.</em></div>';for(let i=0;i<=75;i++){let t=tileType(i),el=document.createElement('div');el.className='tile '+TYPES[t][0];el.dataset.pos=i;el.innerHTML=`<span class=\"num\">${i}</span><span class=\"tile-label\">${TYPES[t][1]}</span>`;b.appendChild(el)}game.players.forEach(p=>{let e=document.createElement('div');e.className='piece';e.id='piece'+p.id;e.textContent=p.fruit;b.appendChild(e)});positionTiles()}\nfunction positionTiles(){let board=$('#board'),r=board.getBoundingClientRect();if(r.width<1||r.height<1)return;let pad=Math.max(28,Math.min(r.width,r.height)*.055),left=pad,top=pad,right=r.width-pad,bottom=r.height-pad,w=right-left,h=bottom-top,perimeter=w*2+h*2;$$('.tile').forEach(el=>{let i=+el.dataset.pos,d=(i/76)*perimeter,x,y;if(d<w){x=left+d;y=top}else if(d<w+h){x=right;y=top+d-w}else if(d<w*2+h){x=right-(d-w-h);y=bottom}else{x=left;y=bottom-(d-w*2-h)}el.style.left=x+'px';el.style.top=y+'px'})}\nfunction posPiece(p){let t=$(`.tile[data-pos=\"${p.pos}\"]`),e=$('#piece'+p.id);if(!t||!e)return;let a=t.getBoundingClientRect(),b=$('#board').getBoundingClientRect(),same=game.players.filter(q=>q.pos===p.pos),index=same.indexOf(p),angle=index*2*Math.PI/Math.max(same.length,1);e.style.left=(a.left-b.left+a.width/2+Math.cos(angle)*10)+'px';e.style.top=(a.top-b.top+a.height/2+Math.sin(angle)*10)+'px';e.classList.toggle('active',game.players[game.current]===p)}\nfunction render(){if(!game)return;let p=game.players[game.current];$('#clockNumber').textContent=game.clock;$('#clockFill').style.width=(game.clock/game.maxClock*100)+'%';$('.clock-bar').classList.toggle('danger',game.clock<=8);$('#clockWarning').textContent=game.clock<=8?'MIDNIGHT NEARS!':'The Cado King watches.';$('#turnBanner').textContent=game.over?'Game over':`${p.fruit} ${p.name}'s turn${p.ai?' (AI)':''}`;$('#playerList').innerHTML=game.players.map((x,i)=>`<div class=\"player-card ${i===game.current?'active':''} ${x.skip?'dead':''}\" style=\"border-left:5px solid ${x.color}\"><span class=\"fruit\">${x.fruit}</span><span class=\"name\">${x.name}${x.ai?' 🤖':''}</span><small>Space ${x.pos} · ${x.points} pts ${x.skip?'· skipped next':''}${x.immunity?' · shield '+x.immunity:''}</small></div>`).join('');$('#shop').innerHTML=[['+5 this roll',4,'boost5'],['+3 for 2 rolls',5,'boost3'],['Shield (2 turns)',6,'immunity']].map(x=>`<button class=\"shop-item\" data-buy=\"${x[2]}\">${x[0]} — ${x[1]} pts</button>`).join('');game.players.forEach(posPiece);$('#rollBtn').disabled=game.phase!=='roll'||p.ai||game.over;$('#endBtn').disabled=game.phase!=='end'||p.ai||game.over;save()}\nfunction startTurn(){if(game.over)return;let p=game.players[game.current];game.phase='roll';p.extra=false;if(p.skip){p.skip--;message(`${p.fruit} ${p.name} is blocked and loses this turn.`);render();setTimeout(nextTurn,1100);return}message(`${p.fruit} ${p.name}, roll the dice!`);render();if(p.ai)setTimeout(aiTurn,900)}\nfunction roll(){let p=game.players[game.current];if(game.phase!=='roll'||p.ai)return;doRoll(p)}\nfunction doRoll(p){game.phase='moving';$('#dice').classList.add('rolling');setTimeout(()=>{let a=1+Math.floor(Math.random()*6),d=1+Math.floor(Math.random()*6),bonus=p.boost5?5:(p.boost3?3:0);if(p.boost5)p.boost5=0;if(p.boost3)p.boost3--;$('#dice').innerHTML=`<b>${a}</b><b>${d}</b>`;$('#dice').classList.remove('rolling');let steps=a+d+bonus;message(`${p.fruit} rolled ${a+d}${bonus?' + '+bonus+' boost':''}!`);sound(440);moveAnimated(p,steps,()=>land(p));},600)}\nfunction moveAnimated(p,n,done){let target=Math.max(0,Math.min(75,p.pos+n)),dir=Math.sign(target-p.pos),count=Math.abs(target-p.pos),i=0;let timer=setInterval(()=>{p.pos+=dir;posPiece(p);sound(260);if(++i>=count){clearInterval(timer);done()}},110)}\nfunction move(p,n){p.pos=Math.max(0,Math.min(75,p.pos+n));}\nfunction land(p){if(p.pos>=75){win(p);return}let type=tileType(p.pos);let text='A quiet stretch of road.';if(type==='roll'){p.extra=true;text='Roll Again! The rebel road calls for another turn.'}if(type==='back'){text='Back 5 spaces!';moveAnimated(p,-5,()=>finishLand(p,text));return}if(type==='swap'){let r=rival(p);if(r&&!r.immunity){swap(p,r);text=`Swapped with ${r.fruit} ${r.name}!`}else text='Swap blocked by a shield.'}if(type==='bad'){if(p.immunity){text='Bad luck deflected by your shield!'}else{p.skip++;p.points=Math.max(0,p.points-2);text='Bad Luck: lose 2 points and skip your next turn.'}}if(type==='event'){drawCard(p);return}finishLand(p,text)}\nfunction finishLand(p,text){if(p.pos>=75){win(p);return}game.phase='end';message(text);render();if(p.ai)setTimeout(nextTurn,700)}\nfunction drawCard(p){let card=EVENTS[Math.floor(Math.random()*EVENTS.length)],apply=()=>{closeModal();card[3](p);if(p.pos>=75){win(p);return}finishLand(p,`Event: ${card[0]}`)};$('#modalContent').innerHTML=`<div class=\"event-card\"><div class=\"card-icon\">${card[1]}</div><p class=\"eyebrow\">Event Card</p><h2>${card[0]}</h2><p>${card[2]}</p><button id=\"cardOk\" class=\"primary\">Accept Fate</button></div>`;openModal();$('#cardOk').onclick=apply;if(p.ai)setTimeout(apply,1200)}\nfunction rival(p){let others=game.players.filter(x=>x!==p);return others.sort((a,b)=>b.pos-a.pos)[0]||null}function swap(a,b){if(!b)return;[a.pos,b.pos]=[b.pos,a.pos]}\nfunction nextTurn(){if(game.over)return;let p=game.players[game.current];if(!p.extra){game.clock--;game.players.forEach(x=>{if(x.immunity)x.immunity--});if(game.clock<=0){lose();return}}game.current=(game.current+1)%game.players.length;startTurn()}\nfunction endTurn(){if(game.phase==='end')nextTurn()}\nfunction buy(kind){let p=game.players[game.current],cost={boost5:4,boost3:5,immunity:6}[kind];if(p.ai||game.phase!=='roll'||p.points<cost)return;p.points-=cost;if(kind==='immunity')p.immunity=Math.max(p.immunity,2);else p[kind]+=(kind==='boost3'?2:1);message('Purchase made. Roll when ready.');sound(600);render()}\nfunction aiTurn(){let p=game.players[game.current];if(!p.ai||game.over||game.paused)return;let choice=p.level==='hard'?(p.pos>60?'boost5':p.immunity?'': 'boost3'):p.level==='normal'&&p.pos>50?'boost5':'';if(choice&&p.points>=({boost5:4,boost3:5}[choice]))buyAi(p,choice);setTimeout(()=>{if(!game.paused)doRoll(p)},500)}function buyAi(p,k){p.points-={boost5:4,boost3:5}[k];p[k]+=(k==='boost3'?2:1)}\nfunction win(p){game.over=true;game.phase='over';render();clearSave();$('#modalContent').innerHTML=`<div class=\"win\"><div class=\"winner-fruit\">${p.fruit}</div><h2>${p.name} Saves the Realm!</h2><p>The rebel reaches the finish before midnight. The Cado King’s reign crumbles!</p><button id=\"playAgain\" class=\"primary\">Play Again</button></div>`;openModal();$('#playAgain').onclick=()=>{closeModal();setup()};sound(800)}\nfunction lose(){game.over=true;clearSave();render();$('#modalContent').innerHTML='<div class=\"win\"><div class=\"winner-fruit\">🥑👑</div><h2>The Cado King Wins</h2><p>Midnight strikes before a rebel can reach the goal. Start a new rebellion!</p><button id=\"playAgain\" class=\"primary\">Try Again</button></div>';openModal();$('#playAgain').onclick=()=>{closeModal();setup()};sound(120)}\nfunction message(t){$('#actionText').textContent=t;$('#turnBanner').classList.add('turn-toast');setTimeout(()=>$('#turnBanner').classList.remove('turn-toast'),700)}function openModal(){$('#modal').classList.remove('hidden')}function closeModal(){$('#modal').classList.add('hidden')}\nfunction rules(){return `<div class=\"rules\"><h2>Rules of AvacaDO</h2><h3>Goal & Setup</h3><p>Choose your rebel fruit and race from space 0 to the Goal at space 75. The Cado King wins if the central doomsday clock reaches zero.</p><h3>Turns & Movement</h3><p>On your turn roll two dice. Your piece moves automatically. Follow the landed tile, optionally buy one market item before rolling, then end your turn. Every normal completed turn lowers the clock by one. A “roll again” or certain card gives an extra turn without lowering it.</p><h3>Tiles</h3><p><b>EVENT</b> draws a card. <b>ROLL AGAIN</b> grants another turn. <b>BACK 5</b> moves you backward. <b>SWAP</b> trades places with the leading rival unless shielded. <b>BAD LUCK</b> costs 2 points and blocks your next turn, unless you have a shield.</p><h3>Cards & Abilities</h3><p>Twenty event outcomes can move rebels, alter points, block rivals, swap places, grant shields, or restore two clock turns. Spend points before rolling: +5 this roll (4), +3 for two rolls (5), or a two-turn shield (6).</p><h3>Winning</h3><p>The first rebel to reach or pass space 75 wins immediately. If all clock turns expire first, the Cado King ends the realm.</p></div>`}\nfunction sound(freq){if(localStorage.avacadoMute==='1')return;try{let c=audio||(audio=new AudioContext()),o=c.createOscillator(),g=c.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.04,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.11);o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+.12)}catch(e){}}\n$('#newGameBtn').onclick=setup;$('#backBtn').onclick=()=>show('startScreen');$('#startBtn').onclick=newGame;$('#rollBtn').onclick=roll;$('#endBtn').onclick=endTurn;$('#restartBtn').onclick=()=>{if(confirm('Restart this game?'))setup()};$('#resetSaveBtn').onclick=()=>{clearSave();message('Saved game removed.')};$('#closeModal').onclick=closeModal;$$('[data-open=\"rules\"]').forEach(b=>b.onclick=()=>{$('#modalContent').innerHTML=rules();openModal()});$('#shop').onclick=e=>{let b=e.target.closest('[data-buy]');if(b)buy(b.dataset.buy)};$('#pauseBtn').onclick=()=>{if(game.over)return;game.paused=true;$('#modalContent').innerHTML='<div class=\"pause\"><h2>Game Paused</h2><p>The rebels catch their breath.</p><button id=\"resume\" class=\"primary\">Resume</button></div>';openModal();$('#resume').onclick=()=>{game.paused=false;closeModal();if(game.players[game.current].ai)aiTurn()}};$('#muteBtn').onclick=function(){localStorage.avacadoMute=localStorage.avacadoMute==='1'?'0':'1';this.textContent=localStorage.avacadoMute==='1'?'🔇':'🔊'};$('#musicBtn').onclick=function(){this.classList.toggle('on');this.textContent=this.classList.contains('on')?'♫ Music On':'♫ Music'};window.addEventListener('resize',()=>{if(game){positionTiles();game.players.forEach(posPiece)}});if(localStorage.getItem('avacadoSave'))$('#continueBtn').classList.remove('hidden');$('#continueBtn').onclick=()=>{try{game=JSON.parse(localStorage.avacadoSave);show('gameScreen');buildBoard();render();startTurn()}catch(e){clearSave()}};\n"};

const contentTypes = {
  "index.html": "text/html; charset=utf-8",
  "styles.css": "text/css; charset=utf-8",
  "game.js": "text/javascript; charset=utf-8"
};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    let path = decodeURIComponent(url.pathname);

    if (path === "/" || path === "") {
      path = "/index.html";
    }

    const key = path.replace(/^\//, "");
    const body = files[key];

    if (!body) {
      return new Response(files["index.html"], {
        headers: {
          "content-type": contentTypes["index.html"],
          "cache-control": "no-store"
        }
      });
    }

    return new Response(body, {
      headers: {
        "content-type": contentTypes[key] || "application/octet-stream",
        "cache-control": "no-store"
      }
    });
  }
};
